// v5.6: 「公开到局域网」—— 只对「本机服务」有意义（局域网发现端点长在房主自己的 Node 上，
// 且 server 侧只接受回环来源拨动开关）。默认不公开：/lan/rooms 只列房主显式公开过的房间，
// 否则同一 Wi-Fi 上的任何设备都能枚举房号、无需邀请进房。
const [lanPub, setLanPub] = useState(false);
const [lanBusy, setLanBusy] = useState(false);
const canLanPub = !!(window.__SP_LOBBY && typeof window.__SP_LOBBY.toggleLanPublic === 'function') && localService;
const toggleLanPub = () => {
  if (!canLanPub || lanBusy) return;
  setLanBusy(true);
  // 与 togglePub 同规：同步异常也折进 promise，别把 busy 钉死。
  var p;
  try { p = Promise.resolve(window.__SP_LOBBY.toggleLanPublic(code, !lanPub)); }
  catch (e) { p = Promise.resolve({ ok: false }); }
  p.then((r) => {
    setLanBusy(false);
    if (r && r.ok) { setLanPub(!!r.on); setPubNote(''); }
    else { setPubNote('局域网公开失败，请重试'); }
  }).catch(() => { setLanBusy(false); setPubNote('局域网公开失败，请重试'); });
};
