${localService ? html`<${Button} size="sm" disabled=${!canLanPub || lanBusy}
  title=${canLanPub ? (lanPub ? '当前已公开到局域网，点击转私密' : '同一 Wi-Fi 下的玩家可在「大厅 → 局域网」里看到并加入') : '暂不能公开'}
  style=${`width:100%;border-color:${lanPub ? '#4ed8af' : '#e06c5a'};color:${lanPub ? '#4ed8af' : '#e06c5a'}`}
  onClick=${toggleLanPub}>${lanBusy ? '公开中…' : (lanPub ? '已公开到局域网 · 点击转私密' : '公开到局域网')}<//>` : null}
